export const stabilityMeta={slug:'training/stability',title:'Training Stability and Generalization',description:'Diagnose loss regimes and gradient flow, clip with the correct contract, resume the complete run, and choose checkpoints using shortcut resistance and measured transfer.',date:'2026-05-11',updated:'2026-10-14',topicPath:['training'],tags:['gradient norm','clipping','loss spikes','resume','checkpoint selection','mode-hopping','generalization','transfer'],learningGoals:['Separate gradient, optimizer update and generalization diagnostics.','Test recovery and resume correctness without guessing causes from curves.','Compare base checkpoints through matched post-training and held-out transfer.'],related:['models/moe','training/optimization','training/data','math/statistics'],prototype:true,visibility:'public',kind:'dense-topic'};
