export const stabilitySections=[['signals','Separate four questions about a run'],['norm','Measure gradients before interpreting them'],['layers','Compare layers and actual parameter changes'],['clipping','Cap a gradient without changing its direction'],['clip-lab','See norm clipping and value clipping differ'],['optimizer','A clipped gradient is not a bounded Adam update'],['threshold','Choose a threshold from a specified run'],['order','Accumulate, synchronize, unscale, then clip'],['distributed','Count each logical gradient once'],['patterns','Judge the new regime, not just the peak'],['timeline-lab','Follow recovery and false improvement'],['observed-curves','Compare the original run traces'],['gradual','A run can fail without a sharp spike'],['resume','A checkpoint contains more than weights'],['repetition','Repeated data can look like progress'],['domains','Separate mixture movement from source degradation'],['mixture-lab','Change the mixture while domain losses stay fixed'],['response','Make the investigation reproducible'],['moe','Some failures take a long time to appear'],['generalization','Smooth loss does not certify shortcut resistance'],['probes','Make the shortcut conflict with the task'],['checkpoints','Inspect three reported checkpoints'],['fluctuations','What the stability checks do and do not exclude'],['transfer','Compare adaptation from two base checkpoints'],['hypothesis','Capacity competition remains a hypothesis'],['selection-data','Data selection is promising but preliminary'],['workflow','Choose a base through held-out transfer'],['limits','Do not select a proxy after seeing its winner'],['sources','References and connected topics']];
