const paper='https://arxiv.org/html/2609.33150v1';
const engineering='https://github.com/stas00/ml-engineering/blob/master/training/instabilities/training-loss-patterns.md';
const table=(c,h,r)=>baseTable(c,h,r).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" tabindex="0" role="region" aria-label="Scrollable table">');
const figure=(folder,name,alt,label,source,guide,legend='')=>`<figure class="stability-figure"><div class="stability-figure-meta"><b>${label}</b><a href="/img/${folder}/${name}" target="_blank" rel="noopener">Open full-size ↗</a></div><a href="/img/${folder}/${name}" target="_blank" rel="noopener" aria-label="Open full-size: ${alt}"><img src="/img/${folder}/${name}" alt="${alt}" loading="lazy"></a>${legend?`<img src="/img/${folder}/${legend}" alt="Blue: larger model; yellow: smaller model; star: Chinchilla-optimal reference." loading="lazy">`:''}<figcaption><b>How to read it.</b> ${guide} ${cite(source,'Original context')}</figcaption></figure>`;
const study=(n,a,l,s,g,legend='')=>figure('generalization-dynamics',n,a,l,paper+s,g,legend);
const curve=(n,a,l,g)=>figure('training-loss-patterns',n,a,l,engineering,g);
const scene=(name,title,controls,body,play=false)=>`<div class="topic-scene" data-stability-lab="${name}"><h3>${title}</h3>${controls}${play?'<div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div>':''}<div data-body>${body}</div></div>`;
function clipBody(tau,kind){const c=clipGradient([6,8],tau,kind),[x,y]=c.gradient,sx=v=>40+v*31,sy=v=>310-v*31;return `<svg viewBox="0 0 390 365" role="img" aria-label="Raw gradient 6,8; ${kind} clipping at ${tau} gives ${x.toFixed(2)},${y.toFixed(2)}"><path d="M40 25V310H355" fill="none" stroke="#93748a"/><circle cx="40" cy="310" r="${tau*31}" fill="none" stroke="#eadbad" stroke-dasharray="5 5"/><path d="M40 310L226 62" stroke="#bd738e" stroke-width="5"/><path d="M40 310L${sx(x)} ${sy(y)}" stroke="#bad6fa" stroke-width="3"/><circle cx="${sx(x)}" cy="${sy(y)}" r="6" fill="#bad6fa"/><text x="180" y="40">Raw (6,8)</text><text x="50" y="338">g₁ →</text><text x="10" y="25">g₂</text></svg><p>Raw L₂ norm=10. Threshold τ=${tau.toFixed(1)}. ${kind==='norm'?(tau===0?'Global norm clipping gives the zero vector; no output direction remains.':'Global norm clipping uses one positive scale and preserves the nonzero direction.'):'Value clipping clamps coordinates separately. The dashed L₂ radius is not its constraint.'} Output=(${x.toFixed(3)}, ${y.toFixed(3)}); output norm=${c.norm.toFixed(3)}. Burgundy: raw vector. Blue: clipped vector. Gold: radius τ.</p><p>${tau===0?'At τ=0 the output is zero, whose direction is undefined.':kind==='value'&&tau<8?'The output can exceed the L₂ threshold even though every coordinate is bounded.':'The constraint depends on the clipping rule, not the label “clip.”'} These are gradients, not parameter-update arrows.</p>`;}
function timelineBody(step,kind){const rows=timeline(kind),selected=rows[step],x=t=>35+t*29,y=l=>250-(l-1.8)*90,path=key=>rows.slice(0,step+1).map((r,i)=>`${i?'L':'M'}${x(r.step)} ${y(r[key])}`).join(' ');return `<svg viewBox="0 0 430 320" role="img" aria-label="Assigned ${kind} example through step ${step}; loss ${selected.loss.toFixed(2)}"><path d="M35 20V270H400" stroke="#93748a" fill="none"/><path d="${path('baseline')}" stroke="#bad6fa" stroke-dasharray="5 5" fill="none" stroke-width="2"/><path d="${path('loss')}" stroke="#bd738e" fill="none" stroke-width="4"/><circle cx="${x(step)}" cy="${y(selected.loss)}" r="6" fill="#eadbad"/><text x="35" y="25">Loss (assigned units)</text><text x="35" y="298">Step index 0 → 12</text></svg><p><strong>Step ${step}: ${selected.phase}.</strong> Assigned loss=${selected.loss.toFixed(2)}; undisturbed reference=${selected.baseline.toFixed(2)}. Burgundy: shown loss; dashed blue: assigned reference; gold: current observation.</p><p>${kind==='repeat'?'Steps 4–8 are assigned repeated-data exposure. The low segment is not a better checkpoint; fresh data resumes at step 9.':kind==='fast'?'The pulse at step 5 disappears at step 6.':kind==='slow'?'The assigned disturbance shrinks gradually and disappears at step 11.':kind==='nonrecover'?'The post-event excess persists and grows. Partial decline does not mean full recovery.':'There is no isolated pulse. Upward disturbance eventually overwhelms the baseline decline.'} This is a synthetic explanation, not measured training data or a claim about the cause of a real run.</p>`;}
function mixtureBody(p){const loss=mixtureLoss(p/100);return `${table('Fixed held-out domain losses; only composition changes',['Domain','Loss','Target-token share'],[['Web','2',`${100-p}%`],['Code','4',`${p}%`],['Aggregate',loss.toFixed(2),'100%']])}<p>Aggregate=(1−x)×2+x×4=${loss.toFixed(2)}, with code share x=${(p/100).toFixed(2)}. No domain became better or worse. Increasing code share raises the mean because code has higher assigned loss.</p><p>Real comparisons require the same tokenizer, masks, reduction and fixed evaluation sets. Different loss levels do not alone rank domain quality or usefulness.</p>`;}
function checkpointBody(i){const c=checkpoints[i],xs=[100,230,370],y=v=>215-v*1.7;return `<svg viewBox="0 0 440 295" role="img" aria-label="Three reported accuracies: 81 percent, 0 percent, 81.7 percent. Selected ${c.tokens}">${[0,50,100].map(v=>`<path d="M50 ${y(v)}H395" stroke="#93748a" stroke-dasharray="3 3"/><text x="5" y="${y(v)+6}">${v}%</text>`).join('')}<polyline points="${checkpoints.map((p,j)=>`${xs[j]},${y(p.accuracy)}`).join(' ')}" fill="none" stroke="#93748a" stroke-dasharray="6 6"/>${checkpoints.map((p,j)=>`<circle cx="${xs[j]}" cy="${y(p.accuracy)}" r="${i===j?11:6}" fill="${j===1?'#bd738e':'#bad6fa'}"/><text x="${xs[j]}" y="${y(p.accuracy)+(p.accuracy>50?28:-19)}" text-anchor="middle">${p.accuracy}%</text><text x="${xs[j]}" y="250" text-anchor="middle">${p.tokens}</text>`).join('')}<text x="50" y="280">Pretraining tokens</text></svg><p role="status"><strong>${c.tokens} · ${c.accuracy}% · ${c.state}.</strong> OLMo3-32B, arithmetic answer-sequence probe. Neighboring observations are 20B training tokens apart, not consecutive optimizer steps.</p><p>Only three reported observations are shown. Dashed connectors are visual guides, not intermediate measurements. The 0% point is a result on this shortcut-conflict probe, not evidence that all arithmetic capability disappeared.</p>`;}
function transferBody(i){const m=transfer[i];return `<p><strong>${m.label}</strong></p>${[[m.earlier,'4.5T base'],[m.later,'4.9T base']].map(([v,l],j)=>`<div class="stability-bar"><span>${l}</span><div><i style="width:${v}%;background:${j?'#bd738e':'#bad6fa'}"></i></div><b>${v}%</b></div>`).join('')}<p role="status">Earlier base: +${(m.earlier-m.later).toFixed(1)} percentage points. ${m.detail} Bars use the same 0–100% scale. These are separate experiments, not two terms of a single quality score.</p>`;}
export function stabilityReader(link){return topic(stabilityMeta,stabilitySections,'A run can be stable, improving, and still the wrong checkpoint to adapt.',`
<p>Loss measures the chosen prediction objective. Gradients describe local sensitivity. Optimizer updates change parameters. Held-out behavior tells us what the resulting model does. These quantities are connected, but none is a substitute for the others.</p><p>Start with run correctness: is the data stream valid, and are updates finite and recoverable? Then evaluate usefulness: does the checkpoint solve the intended tasks, resist misleading patterns, and transfer through post-training? Keeping this order avoids treating a generalization fluctuation as a numerical failure—or a smooth loss curve as proof of quality.</p>
${section('signals','Separate four questions about a run',table('Each question needs its own evidence',['Question','Useful telemetry','What it does not establish'],[['Is the objective improving?','Training/held-out loss with fixed reduction','Transfer or resistance to shortcuts'],['Are updates numerically controlled?','Pre-clip norms, updates, nonfinite counts','Correct data or desired behavior'],['Is the run reproducible?','Sampler/RNG/state lineage; branch replay','Bitwise equivalence under every backend'],['Which checkpoint should be adapted?','Matched post-training; held-out transfer','An unconditional ranking for every task']]))}
${section('norm','Measure gradients before interpreting them',`${eq(String.raw`g=\nabla_\theta\mathcal L,\qquad\|g\|_2=\sqrt{\sum_ig_i^2}`,'Flatten the gradients of the selected logical parameters. State the loss and its reduction.')}<p>A large norm can accompany rare examples, a loss-scale change or unstable activations. A small norm can accompany convergence, saturation, a disconnected path or cancellation. Neither is a model-quality score. Stable norms can coexist with wrong labels, repeated data or weak transfer.</p><p>Record the norm before clipping. A constant post-clip norm can hide widely varying raw gradients. Log the clipping coefficient, nonfinite values, effective target-token count and learning rate alongside the norm.</p><p>Do not compare raw values across changed sum/mean reductions or scaling conventions. Multiplying the loss by a constant multiplies its gradient. Batch-size changes can change noise, averaging and source composition. Check those controls before attributing a trend to better optimization.</p>`)}
${section('layers','Compare layers and actual parameter changes',`<p>Layerwise norms localize unequal gradient flow. Tiny early-layer gradients may suggest vanishing propagation; they can also reflect frozen parameters or masks. A large head norm can signal local sensitivity without proving that the backbone is inactive.</p>${eq(String.raw`r_{\rm gradient,\ell}=\frac{\|g_\ell\|_2}{\|\theta_\ell\|_2},\qquad r_{\rm update,\ell}=\frac{\|\Delta\theta_\ell\|_2}{\|\theta_\ell\|_2}`,'The second ratio uses the actual optimizer step. A zero parameter norm makes either ratio undefined.')}<p>The original norm-to-parameter ratio is useful within a specified parameterization. It is not the actual update ratio under adaptive optimization. Compare parameter classes, optimizer moments and weight decay separately. Keep absolute norms too; a denominator near zero can exaggerate a ratio.</p><p>Early norms often differ from later norms, but monotonic decline is not a universal health rule. Use a known-good run with the same recipe and a distribution of observations, not one ideal curve.</p><p>Warmup changes the learning rate during the early run. It does not directly bound gradients. Compare the gradient distribution and actual updates while the learning rate changes. <a href="${link('training/optimization')}#schedules">Learning-rate schedules →</a></p>`)}
${section('clipping','Cap a gradient without changing its direction',`${eq(String.raw`g_{\rm clip}=\begin{cases}g\min\!\left(1,\frac{\tau}{\|g\|_2}\right)&\|g\|_2>0\\0&g=0\end{cases},\qquad\tau\ge0`,'Global norm clipping applies one scalar to all selected coordinates.')}<p>Recurrent and deep networks can produce large gradients through repeated transformations. Rare batches and high learning rates can also create unstable steps. Clipping limits a finite gradient spike; it is not the primary optimization method or a repair for nonfinite values.</p><p>Above the threshold, global norm clipping preserves the nonzero gradient's direction and limits its L₂ norm. With ${inlineMath(String.raw`g=(6,8)`)} and ${inlineMath(String.raw`\tau=5`)}, the norm is 10, the scale is 0.5 and the result is (3,4).</p><p>Value clipping clamps each coordinate to [−τ,τ]. The same example becomes (5,5), whose L₂ norm is about 7.07. Value clipping generally changes direction; it satisfies a coordinate bound, not an L₂ bound.</p><p>Per-layer norm clipping applies different scalars to different blocks. Each block's direction survives, but the direction of the full vector generally changes. Name the rule and selected parameter set instead of recording only “clipping=1.”</p>`)}
${section('clip-lab','See norm clipping and value clipping differ',scene('clip','Keep the vector fixed; vary its constraint','<label>Threshold<input type="range" aria-label="Clipping threshold" min="0" max="8" step="0.5" value="5"></label><label>Rule<select aria-label="Clipping rule"><option value="norm">Global L₂ norm</option><option value="value">Coordinate value</option></select></label>',clipBody(5,'norm')))}
${section('optimizer','A clipped gradient is not a bounded Adam update',`${eq(String.raw`\Delta\theta=-\eta g_{\rm clip}\quad\Longrightarrow\quad\|\Delta\theta\|_2\le\eta\tau`,'η≥0 and τ≥0. This bound excludes momentum, adaptive preconditioning and separate weight decay.')}<p>Adam uses running first and second moments. Clipping changes their inputs, but the resulting step depends on history and coordinate-wise scaling. Muon transforms update geometry differently. The raw gradient direction is not necessarily the eventual update direction.</p><p>For Adam's first bias-corrected step with zero moments, the update factor is ${inlineMath(String.raw`\frac{g_i}{|g_i|+\epsilon}`)}. Take ${inlineMath(String.raw`\epsilon=0.01`)} and ${inlineMath(String.raw`g=(6,8)`)}. The factors are approximately (${firstAdam([6,8]).map(x=>x.toFixed(4)).join(', ')}). Clipping to (3,4) gives (${firstAdam([3,4]).map(x=>x.toFixed(4)).join(', ')}), not half the original step.</p><p>This is a worked first-step example, not a full Adam trajectory. Separate decoupled decay can move parameters even when the data gradient is zero. Measure actual update norms when update size is the concern. <a href="${link('training/optimization')}#adam">Optimizer memory and geometry →</a></p>`)}
${section('threshold','Choose a threshold from a specified run',`<p>Thresholds such as 1.0 or 0.5 are recipe starting points, not universal safe values. The appropriate scale depends on reduction, effective batch, architecture, optimizer and selected parameters.</p><p>Inspect raw-norm quantiles, clip fraction, scale-factor distribution, nonfinite events and validation. Frequent clipping may be intentional. It may also indicate a threshold mismatch, high learning rate or a changed data distribution. Rare clipping does not prove that updates are safe.</p><p>Compare a controlled threshold change from the same checkpoint and stream. Preserve learning-rate and schedule context. Clipping may prevent a finite outlier from destabilizing a run; it does not repair corrupted state, invalid examples, overflow or a wrong objective.</p>`)}
${section('order','Accumulate, synchronize, unscale, then clip',`<p>Accumulate the intended effective batch with a consistent reduction. Complete the required distributed synchronization. If using scaled mixed-precision gradients, unscale once after accumulation. Then check finiteness, clip, and step.</p><p>Clipping each microbatch changes the objective's combined direction. For equal-weight ${inlineMath(String.raw`g_1=(100,0)`)} and ${inlineMath(String.raw`g_2=(-99,1)`)}, their mean is (0.5,0.5), below ${inlineMath(String.raw`\tau=1`)}. Clipping each first nearly cancels the first coordinate and leaves a tiny second component. The operations do not commute.</p><pre><code># PyTorch sketch: one optimizer; equal-size microbatch means.
optimizer.zero_grad(set_to_none=True)
for batch in microbatches:
    with torch.autocast("cuda", dtype=torch.float16):
        loss = loss_fn(model(batch.x), batch.y) / len(microbatches)
    scaler.scale(loss).backward()
scaler.unscale_(optimizer)  # once, after the effective batch
norm = torch.nn.utils.clip_grad_norm_(
    model.parameters(), tau, error_if_nonfinite=True)
scaler.step(optimizer)
scaler.update()</code></pre><p>This sketch fails fast on nonfinite gradients. A recover-and-skip policy must explicitly check after unscaling and coordinate the skipped step, scheduler and scaler. Do not assume the default nonfinite behavior of clipping makes a bad gradient safe.</p><p>Unequal target-token counts need globally consistent weighting, not equal microbatch means. DDP synchronization must finish before this clipping call; no_sync, sharding and multiple optimizers need their framework-specific implementation. Keep the scale constant within an accumulation window. ${cite('https://docs.pytorch.org/docs/2.12/notes/amp_examples.html','PyTorch AMP ordering')}</p>`)}
${section('distributed','Count each logical gradient once',`<p>A logical global norm is the square root of the sum of squared norms over disjoint gradient coordinates. Summing norms instead of squared norms is wrong. Counting replicated DDP gradients on every rank inflates the result; missing sharded coordinates deflates it.</p><p>Use the framework's distributed-aware clipping operation. Parameter and expert ownership determine which ranks contribute which coordinates. Gradient reduction precision matters separately from norm-reduction precision. Validate a small distributed case against a single logical reference.</p><p>A nonfinite norm is a diagnostic event, not a request for a stronger threshold. Preserve the failed batch and checkpoint metadata. Repeated skips can silently invalidate the assumed optimizer-step and exposure budgets.</p>`)}
${section('patterns','Judge the new regime, not just the peak',`<p>A spike's height does not tell you whether the run recovered. Compare with the expected trajectory and held-out behavior. Check whether the curve returns to the old regime or continues from a worse plateau.</p>${table('Patterns guide investigation; they do not identify causes',['Pattern','What to establish','Possible response'],[['Fast recovery','Loss, gradients and validation return','Continue with an event marker and monitoring'],['Slow recovery','Recovery is genuine, not a worse plateau','Inspect data, state and opportunity cost'],['Incomplete recovery','Persistent excess or deterioration','Pause, preserve evidence, branch from a valid checkpoint'],['Gradual divergence','Sustained deterioration without a pulse','Check optimizer, precision, data and distributed correctness'],['Resume artifact','Event correlates with restored state/mixture','Reproduce and repair restoration'],['False low loss','Repeated exposure changes the comparison','Audit stream IDs before celebrating an improvement'],['Source-specific spike','One fixed source loss changes rather than only its mixture share','Inspect that source’s parsing, labels and delivery path']])}<p>These actions depend on cost, risk and available evidence. Skipping a suspect batch or changing learning rate is an intervention to test, not a diagnosis inferred from a line plot.</p>`)}
${section('timeline-lab','Follow recovery and false improvement',scene('timeline','Reveal the assigned trajectory','<label>Step<input type="range" aria-label="Timeline step" min="0" max="12" step="1" value="0"></label><label>Pattern<select aria-label="Loss pattern"><option value="fast">Fast recovery</option><option value="slow">Slow recovery</option><option value="nonrecover">Incomplete recovery</option><option value="gradual">Gradual divergence</option><option value="repeat">Repeated-data low loss</option></select></label>',timelineBody(0,'fast'),true))}
${section('observed-curves','Compare the original run traces',`<p>These snapshots come from different model sizes, datasets and logging systems. Compare shapes within each plot, not absolute loss or horizontal units across plots. Unsmooth and smoothed traces can differ; read the surrounding run logs before assigning a cause.</p>${curve('bloom-176B-success.png','BLOOM-176B loss declines with a recoverable spike near 30 thousand steps','BLOOM-176B · measured training log','Horizontal: logged training progression. Vertical: LM loss. Follow the orange trend before and after the spike; the source reports recovery in 200 steps. This is not a requirement that every healthy run match this shape.')}${curve('pre-bloom-tr1-13B-glitch-1-2.png','Pre-BLOOM 13B loss has tall spikes followed by return to the declining trend','Pre-BLOOM 13B · fast recovery','The vertical peaks do not create a lasting higher-loss regime. The small original image limits precise reading; no numerical spike-height estimate is reconstructed.')}${curve('idefics-80b-tr-190-01-spike-recover-2023-05-30.png','IDEFICS-80B per-token loss shows a broad disturbance around step 17.5 thousand','IDEFICS-80B · slow recovery','Horizontal: optimizer step. Vertical: per-token loss. Read the broad elevated region and eventual return near the baseline, not just its maximum.')}${curve('pre-bloom-tr8-104B-glitch-1.png','A 104B training attempt spikes near step seven thousand and settles above the prior trend','Pre-BLOOM 104B · incomplete recovery','The post-spike loss remains above its pre-spike trajectory and starts deteriorating. Partial decline from the peak is not full recovery.')}`)}
${section('gradual','A run can fail without a sharp spike',`<p>A plateau can be ordinary diminishing returns, underfitting, a schedule issue or an implementation bug. Sustained upward drift and increasing oscillation require investigation even without a single dramatic event.</p><p>Compare a smaller known-good run. Check gradient/update norms, activation/logit scales, precision, source losses, initialization, normalization and parallelism. Reproduce from a common checkpoint before combining interventions.</p><p>Bekman's pre-BLOOM account describes several unsuccessful 104B attempts and a later successful 176B recipe with BF16, cleaner data and embedding normalization. This is a combined recipe change, not a controlled proof that one of those changes alone fixes divergence. ${cite(engineering,'Original run accounts')}</p>`)}
${section('resume','A checkpoint contains more than weights',`<p>Restore model weights, optimizer moments, scheduler position, scaler, RNG streams, loader cursor, sampler state and mixture counters. Include packing buffers, prefetched work and distributed ownership when they affect the next batch.</p><p>Test an uninterrupted branch against an interrupted-and-restored branch early. Compare sample IDs, target-token counts, source ratios, losses and updates. Define whether the backend promises exact replay or statistical equivalence; do not silently demand bitwise identity from nondeterministic kernels.</p>${curve('idefics-80b-tr-190-01-image2text.png','IDEFICS loss and image-to-text ratio change at marked resume boundaries','IDEFICS-80B · resume correlation','The upper panel is per-token loss; the lower panel is the loader image-to-text ratio. Red marks identify resumes. The source diagnoses loader ratio fluctuations. Correlation in this picture is useful context, not a universal explanation for restart spikes.')}<p>Check log lineage too. A rollback can leave stale future observations in a dashboard. New and old branches must not masquerade as one continuous trajectory. Preserve the parent checkpoint and data exposure rather than relying on a plot's step number alone.</p>`)}
${section('repetition','Repeated data can look like progress',`<p>If the loader restarts from an old cursor, already-seen material can produce a lower training loss. When fresh data returns, the mean rises. That rise may end a false improvement rather than begin a new instability.</p>${curve('ptl-repeat-data-p3.png','Stitched training curves contain lower-loss repeated-data segments followed by higher fresh-data loss','Repeated-data artifact · measured snapshot','The snapshot does not retain labeled axes or a complete legend. Read it qualitatively with the source account: rollback branches repeated data, then returned to fresh material. Do not extract exact loss or elapsed-token numbers from this image.')}<p>Track document/shard IDs, duplicate exposure and loader position. Keep held-out evaluation independent of the repeated segment. Accidental replay invalidates ablations that assumed equal novel exposure. Deliberate epochs are a different, versioned policy; see <a href="${link('training/data')}#caps">source caps and cumulative exposure →</a>.</p>`)}
${section('domains','Separate mixture movement from source degradation',`${eq(String.raw`\mathcal L=\sum_sx_s\mathcal L_s,\qquad x_s\ge0,\quad\sum_sx_s=1`,'x_s is the share under the actual reduction; it need not equal document sampling probability.')}<p>Aggregate loss can move because source losses changed, because composition changed, or both. Log source-specific loss with fixed held-out sets and realized target-token shares. Include web, code, math, multilingual, image-text, synthetic and instruction sources where relevant.</p>${curve('idefics-80b-tr-190-01-losses-2023-06-04.png','IDEFICS source loss traces show both shared and source-local disturbances','IDEFICS-80B · distribution-specific logs','The source identifies cm4 as the high-loss distribution, the average in the middle and pmd below. The screenshot’s truncated legend limits independent color mapping. Inspect simultaneous versus source-local events; different loss levels do not alone prove one dataset has better quality.')}<p>A source-local event suggests inspecting its parsing, labels, length and sampling path. A simultaneous event suggests a shared component, but does not prove one. The same update can affect domains differently.</p>`)}
${section('mixture-lab','Change the mixture while domain losses stay fixed',scene('mixture','An aggregate can rise without degradation','<label>Code target-token share<input type="range" aria-label="Code share" min="0" max="100" step="1" value="50"></label>',mixtureBody(50)))}
${section('response','Make the investigation reproducible',`<ol><li>Mark the event and preserve the preceding checkpoint, batch lineage and full logs.</li><li>Check whether resume, packing, source ratios, precision or throughput changed.</li><li>Compare raw norms, clipping, actual updates, held-out losses and task behavior.</li><li>Inspect a window before the visible event. The last batch need not be its origin.</li><li>Branch a short reproduction with one intervention and a matched control.</li><li>Decide to continue, rollback or change the recipe using recovery and measured cost.</li></ol><p>Reducing learning rate or tightening clipping may suppress symptoms while hiding a broken loader or reduction. Keep unsuccessful reproductions. A hypothesis becomes stronger when it predicts a changed outcome, not when it matches one curve's appearance.</p><p><a href="${link('training/practice')}#metrics">Fault tolerance and goodput →</a> accounts for recovery cost. <a href="${link('training/practice')}#framework">Framework checks →</a> includes state and distributed behavior.</p>`)}
${section('moe','Some failures take a long time to appear',`<p>In MoE, track expert utilization, dead experts, padding share, router/logit scale and head gradients. Allocation can degrade before aggregate loss becomes alarming. Identical padding inputs can concentrate on one expert if routing and balancing count them.</p><p>The Laguna-related original records expert collapse after hundreds of billions of tokens under mismatched Muon learning-rate and effective-decay scaling. It also records a distinct BF16 LM-head input-gradient all-reduce issue under tensor parallelism as logits drifted upward. FP32 stabilized that reduction.</p><p>These are source-specific report observations, not a rule that all MoE failures are Muon problems or all collectives require FP32. Dense early layers can be a recipe choice; they are not a universal cure. <a href="${link('models/moe')}#stability">MoE owns the detailed allocation, numerical and feedback mechanisms →</a></p>`)}
${section('generalization','Smooth loss does not certify shortcut resistance',`<p>Once run correctness is established, a different problem remains: what computation does the model prefer when a tempting pattern conflicts with the task? Wen et al. study that question across saved pretraining checkpoints.</p>${study('overview.png','Schematic contrasts smooth loss and capability growth with three fluctuating generalization patterns','Figure 1 · authors’ conceptual schematic','#S0.F1','The top row summarizes familiar progress pictures. The bottom row illustrates collapse/recovery, oscillation and rare successful episodes. Blue denotes the larger model and yellow the smaller. Stars denote the Chinchilla reference. These are conceptual curves, not measured trajectories.','overview-legend.png')}<p>The authors call behavioral switching mode-hopping. That name does not prove two discrete internal states or an identified circuit replacement. Capability, shortcut resistance and adaptability remain separate evaluation targets. ${cite(paper,'Generalization Dynamics of LM Pre-training')}</p>`)}
${section('probes','Make the shortcut conflict with the task',`<p>The study uses general-pretraining OLMo3-7B/32B and Apertus-8B/70B checkpoints. Main dynamics exclude midtraining and long-context stages. The authors report four random seeds. Their main probing families are:</p>${table('Behavioral tests, not a universal intelligence score',['Probe','Competing shortcut','Task behavior'],[['Flipped labels','Use a familiar label meaning','Infer the demonstrated mapping'],['Repeated answers','Copy a repeated answer','Solve the new instance'],['Successive answers','Continue an answer sequence','Compute even when the sequence breaks'],['Truth/plausibility','Prefer a believable statement','Recognize surprising truths/misconceptions'],['Cognitive reflection','Give the intuitive wrong answer','Solve the underlying relation'],['Multi-hop persona QA','Use disconnected biographical cues','Infer identity and related facts']])}<p>For an arithmetic illustration, demonstrations answer 1, 2, 3; the next problem is 68−60. Continuing the pattern gives 4, while calculation gives 8. Correct ordinary arithmetic examples would not separate those behaviors.</p>${eq(String.raw`m(x)=P_\theta(a_{\rm correct}\mid x)-P_\theta(a_{\rm shortcut}\mid x)`,'A positive pairwise margin favors the task answer over this competitor.')}<p>Most tests compare predefined answer-span probabilities rather than grade free generation. Persona QA uses generation with five questions per persona, sampled 200 times each. Demonstrations are resampled across the four evaluation seeds. Span probability needs consistent tokenization/scoring; the pairwise margin is not unrestricted generation accuracy because a third answer can win.</p><p>The paper also studies function/city out-of-context reasoning after fine-tuning and broader misalignment after insecure-code tuning. These are separate fine-tuning probes, not extra evidence that an output reveals its internal reasoning process.</p>`)}
${section('checkpoints','Inspect three reported checkpoints',`${scene('checkpoint','Observe collapse and recovery without interpolation','<label>Checkpoint<input type="range" aria-label="Reported checkpoint" min="0" max="2" step="1" value="0"></label>',checkpointBody(0),true)}${table('OLMo3-32B arithmetic answer-sequence example',['Pretraining tokens','Reported accuracy'],checkpoints.map(c=>[c.tokens,`${c.accuracy}%`]))}${study('successive-answers.png','Measured shortcut-conflict accuracies fluctuate across OLMo3 checkpoints in four tasks','Figure 4 · measured dynamics','#S3.F4','Horizontal: pretraining tokens in trillions. Vertical: accuracy fraction. Blue is 7B and green 32B. Read each task separately. Stars mark the Chinchilla reference, not the best checkpoint on the probe. The graph samples checkpoints, not every optimizer step.')}`)}
${section('fluctuations','What the stability checks do and do not exclude',`<p>Common benchmarks remain comparatively stable while these conflict probes fluctuate. Continuous probability margins also fluctuate, so hard accuracy's zero crossing is not the whole explanation.</p><p>The single-step experiment restores Adam state, samples OLMo3 data and varies batch size and learning rate. Changes on the suite are small even at the tested learning rate of 10⁻². This establishes local stability for those tests, not that optimization is irrelevant over long intervals.</p><p>Averaging five checkpoints mitigates but does not eliminate mode-hopping in the tested recipe. The paper's averaging figure is Figure 11; the nearby prose links Figure 12 inconsistently. Do not generalize the tested outcome to every averaging policy.</p><p>Cross-dataset correlations are often low. Larger models show more consistent behavior across datasets in these tests, but can still fluctuate. Equal-FLOP comparisons in Appendix H do not show a generalization advantage for larger models. Capacity is not a cost-free fix.</p>`)}
${section('transfer','Compare adaptation from two base checkpoints',`<p>The authors select 4.5T and 4.9T OLMo3-32B bases using their diagnostic suite, then compare post-training. The earlier candidate has stronger suite behavior. The important test is whether this ranking transfers outside the selection probe.</p>${scene('transfer','Keep base lineage separate from the adaptation metric','<label>Experiment<select aria-label="Transfer experiment"><option value="0">Math SFT → science reasoning</option><option value="1">General SFT → attack robustness</option></select></label>',transferBody(0))}${table('Reported post-training endpoints; percentage points, not relative percent',['Metric','4.5T base','4.9T base','Difference'],transfer.map(m=>[m.label,`${m.earlier}%`,`${m.later}%`,`${(m.earlier-m.later).toFixed(1)} pp`]))}${study('post-training-gpqa.png','Math scores improve for both bases but GPQA transfer rises for 4.5T and falls for 4.9T','Figure 13(a) · reasoning transfer','#S5.F13','Top left: MATH-500 accuracy versus SFT steps; top right: GPQA-Diamond. Both bases learn the math domain, but transfer differs. Bottom panels show score changes across additional bases; the 4.5T mark is not necessarily the largest math gain. Read change and endpoint scores separately.')}<p>General SFT uses 49K non-safety examples from official OLMo3 post-training data and 1K safety examples from STAR-1. A prefilling attack supplies an initial assistant continuation intended to steer behavior. Robustness measures the evaluated attack setup, not all safety.</p>${study('post-training-alignment.png','4.5T base gains more prefilling-attack robustness during SFT than 4.9T base','Figure 13(b) · alignment transfer','#S5.F13','Upper panel: robustness versus SFT steps. Lower panel: robustness gains across base pretraining checkpoints. The highlighted early base performs well here; midtraining and later checkpoints do not monotonically improve transfer.')}<p>This supports checkpoint selection in the tested OLMo3-32B setting. It does not establish that earlier bases generally win, or that the same ranking survives every SFT/RL budget and data recipe.</p>`)}
${section('hypothesis','Capacity competition remains a hypothesis',`<p>The authors propose that shallow pattern computations and generalizable computations compete for limited capacity. Different training-data windows may change which computation dominates output.</p><p>Behavioral evidence does not reveal whether a useful circuit was overwritten, became harder to activate or lost a prediction-time competition. The paper does not establish causal circuit replacement. Preserve the distinction between measured switching and this explanation.</p>`)}
${section('selection-data','Data selection is promising but preliminary',`${study('data-selection.png','Controlled data windows stabilize answer-plus-one behavior in opposite directions','Figure 14 · preliminary continuation','#S5.F14','Vertical: accuracy on answer+1. Green selects generalization-associated data, orange pattern-associated data, gray random data. The published horizontal tick labels are non-monotonic. Do not repair the labels or infer exact elapsed-token intervals.')}<p>The authors know which windows improved or harmed this probe in the original run. They select continuation subsets retrospectively. The experiment concerns one arithmetic probe and an intermediate OLMo3-32B base.</p><p>This is not a classifier that labels arbitrary documents as generalizable. A prospective pipeline needs unrelated held-out probes and trade-off checks. Stabilizing one chosen behavior can harm another. <a href="${link('training/data')}#search">Controlled data-mixture search →</a></p>`)}
${section('workflow','Choose a base through held-out transfer',`<p>Use the following as an engineering adaptation, not the authors' exact protocol.</p>${figure('generalization-dynamics','checkpoint-selection.svg','Save candidates, compare capability and shortcut resistance, run matched SFT, select held-out transfer and confirm the budget','Original checkpoint-selection workflow',paper,'The two screening branches ask different questions. They meet at matched adaptation, not at an arbitrary average score. Confirmation at the intended budget prevents a short pilot from becoming an unsupported final guarantee.')}<ol><li>Save several viable bases with full state and data lineage.</li><li>Track fixed held-out NLL, domain capability, conflict margins and a generative audit.</li><li>Shortlist across domains and prompt variants; avoid a one-probe winner.</li><li>Run matched pilot SFT with identical examples, masks, token budgets, recipes and harnesses. Repeat seeds when feasible.</li><li>Select using held-out transfer and relevant robustness constraints.</li><li>Confirm at the intended post-training budget. Different learning curves can reverse the pilot ranking.</li></ol><p>For coding, possible probes include repeated demonstration outputs, misleading templates and short-function adaptation evaluated on held-out repository tasks. These are suggested adaptations, not demonstrated findings from this study.</p>`)}
${section('limits','Do not select a proxy after seeing its winner',`<p>Appendix I tests activation/gradient spectrum metrics and gradient similarity. Correlations depend on dataset and layer. Selecting the best layer gives even a random baseline a correlation around 0.4. This selection effect prevents treating the winning layer's correlation as clean prospective evidence.</p><p>High and low complexity can both accompany good behavior. A gradient norm, effective rank or sharpness proxy cannot replace held-out task evaluation. Fix proxy choices before the final comparison; account for uncertainty and repeated selection.</p><p>The study covers two model families and several templated probes. Selected post-training evidence focuses on OLMo3-32B. Correct answers do not prove a specific reasoning mechanism. Generalization is task-dependent, so keep capability, shortcut resistance, adaptation and run correctness as separate measurements.</p>`)}
${section('sources','References and connected topics',`<p>${cite(paper,'Wen et al., Generalization Dynamics (27 September 2026)')} · ${cite('https://arxiv.org/pdf/2609.33150','Paper PDF')} · ${cite(engineering,'Stas Bekman: training loss patterns')} · ${cite('https://docs.pytorch.org/docs/2.12/generated/torch.nn.utils.clip_grad_norm_.html','PyTorch clipping contract')}</p><p><a href="${link('models/moe')}#stability">MoE stability →</a> · <a href="${link('post-training/sft')}">SFT →</a> · <a href="${link('training/practice')}#experiment">Ablation design →</a> · <a href="${link('training/scaling')}#lifecycle">Inference-aware budgets →</a> · <a href="${link('training/practice')}#smol">Smol development loop →</a></p><p>Paper images are selected attributed research excerpts for commentary. The arXiv distribution license is not an open reuse license. Original axis/legend limitations remain visible. The parameter and recovery examples are synthetic explanations, not additional experimental evidence.</p>`)}
`);}
export {clipBody as stabilityClipBody};
export function mountStability(scope=document){mountTopic(scope,stabilityMeta.slug,article=>{for(const name of ['clip','timeline','mixture','checkpoint','transfer']){const lab=article.querySelector(`[data-stability-lab="${name}"]`),slider=lab.querySelector('input'),select=lab.querySelector('select'),draw=()=>{const v=Number(slider?.value??select.value),body=name==='clip'?clipBody(v,select.value):name==='timeline'?timelineBody(v,select.value):name==='mixture'?mixtureBody(v):name==='checkpoint'?checkpointBody(v):transferBody(v);lab.querySelector('[data-body]').innerHTML=body;};if(['timeline','checkpoint'].includes(name)){const p=rangePlayback(article,lab,draw,15000);select?.addEventListener('change',()=>{p.stop();draw();});}else{slider?.addEventListener('input',draw);select?.addEventListener('change',draw);}draw();}});}
stabilityMeta.searchText=stabilityReader(()=> '').replace(/<[^>]*>/g,' ');
